import { PlayerFactory } from '../player/PlayerFactory';
import { Calendar } from './Calendar';
import { Tournament, TournamentConfig } from '../tournament/Tournament';
import { TrainingManager, TrainingType, TrainingResult } from './TrainingManager';
import { IRandomProvider, DefaultRandomProvider } from '../random/RandomProvider';

export interface CareerEventLog {
  week: number;
  year: number;
  title: string;
  description: string;
  type: 'tournament' | 'training' | 'milestone' | 'news';
}

export class CareerManager {
  public calendar: Calendar;
  public player: Player;
  public eventLogs: CareerEventLog[] = [];
  public activeTournament: Tournament | null = null;
  public availableTournaments: TournamentConfig[] = [];

  constructor(
    player: Player,
    private rng: IRandomProvider = new DefaultRandomProvider()
  ) {
    this.player = player;
    this.calendar = new Calendar(2026, 1);
    this.refreshAvailableTournaments();
  }

  /**
   * Refreshes tournament offerings suitable for current tier
   */
  public refreshAvailableTournaments(): void {
    this.availableTournaments = [
      {
        id: `red-lion-${this.calendar.currentWeek}`,
        name: 'The Red Lion Thursday Open',
        location: 'Coventry, West Midlands',
        tier: 'pub',
        entryFee: 10,
        prizePool: { winner: 120, runnerUp: 50, semiFinalist: 20, quarterFinalist: 0 },
        rankingPoints: { winner: 25, runnerUp: 15, semiFinalist: 8, quarterFinalist: 2 },
        format: { type: 'legs', bestOfLegs: 3, startingScore: 501 }
      },
      {
        id: `fox-hounds-${this.calendar.currentWeek}`,
        name: 'The Fox & Hounds Trophy',
        location: 'Solihull, West Midlands',
        tier: 'pub',
        entryFee: 15,
        prizePool: { winner: 180, runnerUp: 75, semiFinalist: 30, quarterFinalist: 0 },
        rankingPoints: { winner: 35, runnerUp: 20, semiFinalist: 10, quarterFinalist: 3 },
        format: { type: 'legs', bestOfLegs: 3, startingScore: 501 }
      },
      {
        id: `midlands-open-${this.calendar.currentWeek}`,
        name: 'Midlands Amateur Classic',
        location: 'Birmingham',
        tier: 'amateur',
        entryFee: 30,
        prizePool: { winner: 400, runnerUp: 180, semiFinalist: 80, quarterFinalist: 25 },
        rankingPoints: { winner: 70, runnerUp: 45, semiFinalist: 25, quarterFinalist: 10 },
        format: { type: 'legs', bestOfLegs: 5, startingScore: 501 }
      }
    ];
  }

  /**
   * Enters player into a chosen tournament
   */
  public enterTournament(config: TournamentConfig): Tournament {
    if (this.player.bankBalance < config.entryFee) {
      throw new Error(`Insufficient funds (£${this.player.bankBalance}) for entry fee (£${config.entryFee}).`);
    }

    this.player.bankBalance -= config.entryFee;

    // Generate 7 AI participants
    const factory = new PlayerFactory(this.rng);
    const participants: Player[] = [this.player];

    for (let i = 0; i < 7; i++) {
      participants.push(factory.createAIOpponent(config.tier));
    }

    // Shuffle bracket seeding
    const shuffled = [...participants].sort(() => this.rng.next() - 0.5);

    this.activeTournament = new Tournament(config, shuffled, this.rng);

    this.addLog({
      week: this.calendar.currentWeek,
      year: this.calendar.currentYear,
      title: `Entered ${config.name}`,
      description: `Paid £${config.entryFee} entry fee and joined the 8-player knockout bracket.`,
      type: 'tournament'
    });

    return this.activeTournament;
  }

  /**
   * Processes tournament conclusion rewards
   */
  public finalizeTournament(tournament: Tournament): void {
    const pid = this.player.id;
    let prizeWon = 0;
    let pointsWon = 0;

    if (tournament.winner?.id === pid) {
      prizeWon = tournament.config.prizePool.winner;
      pointsWon = tournament.config.rankingPoints.winner;
      this.player.adjustConfidence(20);
      this.addLog({
        week: this.calendar.currentWeek,
        year: this.calendar.currentYear,
        title: `🏆 Champion! Won ${tournament.config.name}`,
        description: `Clinched the title! Earned £${prizeWon} and ${pointsWon} ranking points.`,
        type: 'milestone'
      });
    } else if (tournament.runnerUp?.id === pid) {
      prizeWon = tournament.config.prizePool.runnerUp;
      pointsWon = tournament.config.rankingPoints.runnerUp;
      this.player.adjustConfidence(8);
      this.addLog({
        week: this.calendar.currentWeek,
        year: this.calendar.currentYear,
        title: `Runner-Up in ${tournament.config.name}`,
        description: `Reached the final! Earned £${prizeWon} and ${pointsWon} ranking points.`,
        type: 'tournament'
      });
    } else {
      // Check semi-finalist
      const sfMatches = tournament.rounds[1] || [];
      const reachedSF = sfMatches.some(m => m.player1.id === pid || m.player2.id === pid);
      if (reachedSF) {
        prizeWon = tournament.config.prizePool.semiFinalist;
        pointsWon = tournament.config.rankingPoints.semiFinalist;
      } else {
        prizeWon = tournament.config.prizePool.quarterFinalist;
        pointsWon = tournament.config.rankingPoints.quarterFinalist;
      }
      this.player.adjustConfidence(-4);
      this.addLog({
        week: this.calendar.currentWeek,
        year: this.calendar.currentYear,
        title: `Eliminated from ${tournament.config.name}`,
        description: `Earned £${prizeWon} and ${pointsWon} ranking points.`,
        type: 'tournament'
      });
    }

    this.player.bankBalance += prizeWon;
    this.player.prizeMoneyTotal += prizeWon;
    this.player.rankingPoints += pointsWon;

    // Small fatigue from tournament
    this.player.addFatigue(15);
    this.activeTournament = null;
  }

  public train(type: TrainingType): TrainingResult {
    const res = TrainingManager.executeTraining(this.player, type);
    this.addLog({
      week: this.calendar.currentWeek,
      year: this.calendar.currentYear,
      title: `Training: ${type.toUpperCase()}`,
      description: res.message,
      type: 'training'
    });
    return res;
  }

  public advanceWeek(): void {
    const res = this.calendar.advanceWeek();
    if (res.yearChanged) {
      this.player.age++;
      this.addLog({
        week: 1,
        year: this.calendar.currentYear,
        title: `🎂 Birthday! Turn ${this.player.age}`,
        description: `A new year begins. You are now ${this.player.age} years old.`,
        type: 'news'
      });
    }

    // Natural light recovery if no active tournament
    if (this.player.state.fatigue > 0 && !this.activeTournament) {
      this.player.rest(10);
    }

    this.refreshAvailableTournaments();
  }

  public addLog(log: CareerEventLog): void {
    this.eventLogs.unshift(log);
    if (this.eventLogs.length > 50) this.eventLogs.pop();
  }
}
'''

